 for s in sc:md += [f'### {s["id"]} · {s["title"]}',f'- Surface: {s["surface"]}; primary intent: {s["action"]}',f'- Flow: {s["section"]}; inspect/cancel/back preserve draft; no live effects in fixture',f'- Required states: loading / empty / denied / invalid / pending / confirmed / conflict / unsupported as applicable',f'- Developer invariant: {s["note"]}',f'- Editable frame: frames/{s["id"]}-desktop.svg; compact: frames/{s["id"]}-mobile.svg','']
 for g in gates:md += ['- Acceptance: '+g]
