  summary='# '+title+'\n\nDesign/planning only; no implementation or provider evidence.\n\n'+scope+'\n\n## Screens\n'+'\n'.join('- '+id for id in ids)+'\n\n## Sequential prompts\n'+'\n'.join('- docs/work-plan/'+p for p in prompts)+'\n\n## Acceptance\n'+'\n'.join('- [ ] '+g for g in gates)+'\n\n## Deferred\nNo default switch, merge, deploy, live migration, arbitrary provider delivery or legacy retirement.\n'
